window.bookSummaryJSON = "<p><b>Sacrifices are acceptable when you're not the one making them.</b><br> <br> With Arty's life hanging in the balance, nothing else matters.<br> <br> Until it does.<br> <br> The rift in the abyss is opening. The world as we know it is about to end, and it turns out, I'm the only one who can stop it.<br> <br> <b>It's time to face the ultimate truth.</b><br> <br> <b>It's finally time to face Fate head on.</b><br> <br> Contains mature themes.</p>"; 
